def sha(raw):return hashlib.sha256(raw).hexdigest()
def enc(v):return (json.dumps(v,sort_keys=True,indent=2,ensure_ascii=False,allow_nan=False)+'\n').encode()
def md(s):return [getattr(s,k) for k in KEYS]
def read(path,maximum=MAX_REPORT):
 p=Path(path);need(p.is_absolute() and p.resolve(strict=True)==p,'canonical host source required')
 fd=os.open(p,os.O_RDONLY|os.O_NOFOLLOW|os.O_CLOEXEC)
